int decode_lazy_structure(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    std::stack<int> depth_stack;
    char const* current = start;
    int depth = 0;
    int item_count = 0;

    while (current < end && item_count < item_limit) {
        if (depth >= depth_limit) {
            ec = make_error_code(lazy_error::depth_limit_exceeded);
            if (error_pos) *error_pos = static_cast<int>(current - start);
            return static_cast<int>(ec.value());
        }

        if (*current == '{') {
            // Start of dictionary
            ++depth;
            depth_stack.push(depth);
            ++current;
        }
        else if (*current == '}') {
            // End of dictionary
            if (depth_stack.empty()) {
                ec = make_error_code(lazy_error::unexpected_end_of_input);
                if (error_pos) *error_pos = static_cast<int>(current - start);
                return static_cast<int>(ec.value());
            }
            depth_stack.pop();
            --depth;
            ++current;
        }
        else if (*current == '[') {
            // Start of list
            ++depth;
            depth_stack.push(depth);
            ++current;
        }
        else if (*current == ']') {
            // End of list
            if (depth_stack.empty()) {
                ec = make_error_code(lazy_error::unexpected_end_of_input);
                if (error_pos) *error_pos = static_cast<int>(current - start);
                return static_cast<int>(ec.value());
            }
            depth_stack.pop();
            --depth;
            ++current;
        }
        else if (*current == 'i') {
            // Integer value
            ++current;
            char const* int_end = std::find_if(current, end, [](char c) { return c == 'e'; });
            if (int_end == end) {
                ec = make_error_code(lazy_error::unexpected_end_of_input);
                if (error_pos) *error_pos = static_cast<int>(current - start);
                return static_cast<int>(ec.value());
            }

            // Parse integer and assign to ret
            try {
                int64_t value = std::stoll(std::string(current, int_end));
                ret = value;
                ++item_count;
            }
            catch (const std::exception&) {
                ec = make_error_code(lazy_error::invalid_integer_format);
                if (error_pos) *error_pos = static_cast<int>(current - start);
                return static_cast<int>(ec.value());
            }

            current = int_end + 1;
        }
        else if (*current == ':') {
            // String length delimiter
            ++current;

            char const* str_len_end = std::find_if(current, end, [](char c) { return c == ':'; });
            if (str_len_end == end) {
                ec = make_error_code(lazy_error::unexpected_end_of_input);
                if (error_pos) *error_pos = static_cast<int>(current - start);
                return static_cast<int>(ec.value());
            }

            // Parse string length
            size_t length;
            try {
                length = std::stoul(std::string(current, str_len_end));
            }
            catch (const std::exception&) {
                ec = make_error_code(lazy_error::invalid_string_length);
                if (error_pos) *error_pos = static_cast<int>(current - start);
                return static_cast<int>(ec.value());
            }

            current = str_len_end + 1;
            if (current + length > end) {
                ec = make_error_code(lazy_error::unexpected_end_of_input);
                if (error_pos) *error_pos = static_cast<int>(current - start);
                return static_cast<int>(ec.value());
            }

            std::string str(current, current + length);
            ret = str;
            ++item_count;

            current += length;
        }
        else {
            // Unknown or invalid token
            ec = make_error_code(lazy_error::invalid_token);
            if (error_pos) *error_pos = static_cast<int>(current - start);
            return static_cast<int>(ec.value());
        }
    }

    if (current != end) {
        ec = make_error_code(lazy_error::extra_data_after_end);
        if (error_pos) *error_pos = static_cast<int>(current - start);
        return static_cast<int>(ec.value());
    }

    return 0;
}

int decode_lazy_structure(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    std::stack<int> depth_stack;
    int depth = 0;
    const char* current = start;
    int items_decoded = 0;

    while (current < end && items_decoded < item_limit) {
        if (depth >= depth_limit) {
            ec = make_error_code(lazy_error::depth_limit_exceeded);
            if (error_pos)
                *error_pos = static_cast<int>(current - start);
            return 1;
        }

        switch (*current) {
            case 'd': {
                depth++;
                depth_stack.push(depth);
                // Begin dictionary decoding
                // Assume helper function `decode_dictionary` handles this
                int result = decode_dictionary(current, end, ret, ec, error_pos, depth_limit, depth);
                if (result != 0) {
                    return result;
                }
                current++;
                items_decoded++;
                break;
            }
            case 'l': {
                depth++;
                depth_stack.push(depth);
                // Begin list decoding
                // Assume helper function `decode_list` handles this
                int result = decode_list(current, end, ret, ec, error_pos, depth_limit, depth);
                if (result != 0) {
                    return result;
                }
                current++;
                items_decoded++;
                break;
            }
            case 'i': {
                // Begin integer decoding
                // Assume helper function `decode_integer` handles this
                int result = decode_integer(current, end, ret, ec, error_pos);
                if (result != 0) {
                    return result;
                }
                current += 2; // Skip 'i' and 'e'
                items_decoded++;
                break;
            }
            default:
                ec = make_error_code(lazy_error::invalid_input);
                if (error_pos)
                    *error_pos = static_cast<int>(current - start);
                return 1;
        }
    }

    if (current != end) {
        ec = make_error_code(lazy_error::unexpected_input);
        if (error_pos)
            *error_pos = static_cast<int>(current - start);
        return 1;
    }

    return 0;
}

int decode_lazy_structure(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    std::stack<lazy_entry*> stack;
    stack.push(&ret);
    const char* pos = start;

    while (pos < end && item_limit-- > 0) {
        if (pos >= end) {
            ec = error_code::unexpected_end;
            if (error_pos)
                *error_pos = static_cast<int>(pos - start);
            return static_cast<int>(ec);
        }

        if (depth_limit <= 0) {
            ec = error_code::depth_limit_exceeded;
            if (error_pos)
                *error_pos = static_cast<int>(pos - start);
            return static_cast<int>(ec);
        }

        switch (*pos) {
            case 'd': {
                lazy_entry dict;
                dict.type = lazy_entry::dict;
                stack.push(&dict);
                ++pos;
                break;
            }
            case 'l': {
                lazy_entry list;
                list.type = lazy_entry::list;
                stack.push(&list);
                ++pos;
                break;
            }
            case 'i': {
                ++pos;
                const char* num_start = pos;
                while (pos < end && isdigit(*pos))
                    ++pos;
                if (pos >= end || *pos != 'e') {
                    ec = error_code::invalid_integer;
                    if (error_pos)
                        *error_pos = static_cast<int>(num_start - start);
                    return static_cast<int>(ec);
                }
                std::string num_str(num_start, pos - num_start);
                try {
                    long long value = std::stoll(num_str);
                    lazy_entry integer;
                    integer.type = lazy_entry::integer;
                    integer.value = value;
                    stack.top()->children.emplace_back(integer);
                } catch (...) {
                    ec = error_code::invalid_integer;
                    if (error_pos)
                        *error_pos = static_cast<int>(num_start - start);
                    return static_cast<int>(ec);
                }
                ++pos;
                break;
            }
            case 'e': {
                if (stack.size() <= 1) {
                    ec = error_code::unexpected_end;
                    return static_cast<int>(ec);
                }
                stack.pop();
                ++pos;
                break;
            }
            default:
                if (isdigit(*pos)) {
                    const char* str_start = pos;
                    while (pos < end && isdigit(*pos))
                        ++pos;
                    if (pos >= end || *pos != ':') {
                        ec = error_code::invalid_string;
                        if (error_pos)
                            *error_pos = static_cast<int>(str_start - start);
                        return static_cast<int>(ec);
                    }
                    int length;
                    try {
                        length = std::stoi(std::string(str_start, pos - str_start));
                    } catch (...) {
                        ec = error_code::invalid_string;
                        if (error_pos)
                            *error_pos = static_cast<int>(str_start - start);
                        return static_cast<int>(ec);
                    }
                    ++pos;
                    if (pos + length > end) {
                        ec = error_code::unexpected_end;
                        if (error_pos)
                            *error_pos = static_cast<int>(pos - start);
                        return static_cast<int>(ec);
                    }
                    lazy_entry str;
                    str.type = lazy_entry::string;
                    str.value = std::string(pos, length);
                    stack.top()->children.emplace_back(str);
                    pos += length;
                }
                else {
                    ec = error_code::invalid_data;
                    if (error_pos)
                        *error_pos = static_cast<int>(pos - start);
                    return static_cast<int>(ec);
                }
        }

        --depth_limit;
    }

    if (item_limit <= 0) {
        ec = error_code::item_limit_exceeded;
        return static_cast<int>(ec);
    }

    if (stack.size() > 1) {
        ec = error_code::incomplete_structure;
        return static_cast<int>(ec);
    }

    return 0;
}

int decode_lazy_structure(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    // Stack to manage nested structures during decoding
    std::vector<int> depth_stack;
    std::vector<int> item_stack;
    char const* current = start;
    int depth = 0;
    int items_decoded = 0;

    while (current < end && items_decoded < item_limit) {
        if (depth >= depth_limit) {
            ec = error_code::depth_exceeded;
            if (error_pos)
                *error_pos = static_cast<int>(current - start);
            return static_cast<int>(ec);
        }

        switch (*current) {
            case 'd':
                // Start of dictionary
                depth_stack.push_back(depth);
                item_stack.push_back(items_decoded);
                depth++;
                current++;
                continue;

            case 'l':
                // Start of list
                depth_stack.push_back(depth);
                item_stack.push_back(items_decoded);
                depth++;
                current++;
                continue;

            case 'i':
                // Integer
                ++current;
                char const* int_end = std::find_if(current, end, [](char c) { return c == 'e'; });
                if (int_end == end) {
                    ec = error_code::unexpected_end;
                    if (error_pos)
                        *error_pos = static_cast<int>(current - start);
                    return static_cast<int>(ec);
                }

                try {
                    // Assume lazy_entry has a method to store an integer
                    ret.add_integer(std::stoi(std::string(current, int_end)));
                } catch (std::out_of_range&) {
                    ec = error_code::integer_overflow;
                    if (error_pos)
                        *error_pos = static_cast<int>(current - start);
                    return static_cast<int>(ec);
                }

                current = int_end + 1;
                items_decoded++;
                continue;

            case 'e':
                // End of dictionary or list
                if (depth_stack.empty()) {
                    ec = error_code::unbalanced_end;
                    if (error_pos)
                        *error_pos = static_cast<int>(current - start);
                    return static_cast<int>(ec);
                }

                depth = depth_stack.back();
                items_decoded = item_stack.back();
                depth_stack.pop_back();
                item_stack.pop_back();
                current++;
                continue;

            default:
                // String or invalid character
                if (*current == '\0' || !std::isdigit(*current)) {
                    ec = error_code::invalid_format;
                    if (error_pos)
                        *error_pos = static_cast<int>(current - start);
                    return static_cast<int>(ec);
                }

                // Handle string or other types
                // Assume lazy_entry has a method to store a string
                char const* str_end = std::find_if(current, end, [](char c) { return c == ':'; });
                if (str_end == end) {
                    ec = error_code::unexpected_end;
                    if (error_pos)
                        *error_pos = static_cast<int>(current - start);
                    return static_cast<int>(ec);
                }

                try {
                    int length = std::stoi(std::string(current, str_end));
                    if (current + length > end) {
                        ec = error_code::unexpected_end;
                        if (error_pos)
                            *error_pos = static_cast<int>(current - start);
                        return static_cast<int>(ec);
                    }

                    ret.add_string(std::string(current + (str_end - current) + 1, current + (str_end - current) + 1 + length));
                } catch (std::out_of_range&) {
                    ec = error_code::string_length_overflow;
                    if (error_pos)
                        *error_pos = static_cast<int>(current - start);
                    return static_cast<int>(ec);
                }

                current += (str_end - current) + length + 1;
                items_decoded++;
                continue;
        }
    }

    if (current != end) {
        ec = error_code::trailing_data;
        if (error_pos)
            *error_pos = static_cast<int>(current - start);
        return static_cast<int>(ec);
    }

    if (!depth_stack.empty()) {
        ec = error_code::unbalanced_start;
        if (error_pos)
            *error_pos = static_cast<int>(current - start);
        return static_cast<int>(ec);
    }

    ec = error_code::success;
    return 0;
}

int decode_lazy_structure(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    std::stack<lazy_entry*> stack;
    stack.push(&ret);

    while (start < end && item_limit > 0) {
        if (depth_limit <= 0) {
            ec = error_code::depth_limit_exceeded;
            if (error_pos)
                *error_pos = static_cast<int>(start - start);
            return 1;
        }

        if (*start == 'd') {
            lazy_entry dict;
            if (!dict.init_dict()) {
                ec = error_code::memory_allocation_failed;
                return 1;
            }
            stack.push(&dict);
            ++start;
            continue;
        }
        else if (*start == 'l') {
            lazy_entry list;
            if (!list.init_list()) {
                ec = error_code::memory_allocation_failed;
                return 1;
            }
            stack.push(&list);
            ++start;
            continue;
        }
        else if (*start == 'i') {
            ++start;
            const char* number_end = start;
            while (number_end < end && isdigit(*number_end))
                ++number_end;

            if (number_end == start) {
                ec = error_code::invalid_integer;
                if (error_pos)
                    *error_pos = static_cast<int>(start - start);
                return 1;
            }

            int64_t value = 0;
            try {
                value = std::stoll(std::string(start, number_end));
            }
            catch (...) {
                ec = error_code::invalid_integer;
                if (error_pos)
                    *error_pos = static_cast<int>(start - start);
                return 1;
            }

            lazy_entry integer;
            if (!integer.init_integer(value)) {
                ec = error_code::memory_allocation_failed;
                return 1;
            }

            lazy_entry* top = stack.top();
            if (top->type() == lazy_entry::dict_type) {
                ec = error_code::key_expected;
                if (error_pos)
                    *error_pos = static_cast<int>(start - start);
                return 1;
            }
            else if (top->type() == lazy_entry::list_type) {
                if (!top->list_append(integer)) {
                    ec = error_code::memory_allocation_failed;
                    return 1;
                }
            }
            else {
                ec = error_code::malformed_structure;
                if (error_pos)
                    *error_pos = static_cast<int>(start - start);
                return 1;
            }

            start = number_end + 1; // Skip 'e'
            --item_limit;
            continue;
        }
        else if (*start == 'e') {
            stack.pop();
            ++start;
            continue;
        }
        else {
            // String
            const char* number_end = start;
            while (number_end < end && isdigit(*number_end))
                ++number_end;

            if (number_end == start) {
                ec = error_code::invalid_string_length;
                if (error_pos)
                    *error_pos = static_cast<int>(start - start);
                return 1;
            }

            int string_len = std::stoi(std::string(start, number_end));
            if (start + string_len + 1 > end) {
                ec = error_code::unexpected_end_of_input;
                if (error_pos)
                    *error_pos = static_cast<int>(start - start);
                return 1;
            }

            const char* string_data = number_end;
            const char* string_end = string_data + string_len;

            lazy_entry string_entry;
            if (!string_entry.init_string(string_data, string_len)) {
                ec = error_code::memory_allocation_failed;
                return 1;
            }

            lazy_entry* top = stack.top();
            if (top->type() == lazy_entry::dict_type) {
                if (!top->dict_append(std::string_view(start, number_end), string_entry)) {
                    ec = error_code::memory_allocation_failed;
                    return 1;
                }
            }
            else if (top->type() == lazy_entry::list_type) {
                if (!top->list_append(string_entry)) {
                    ec = error_code::memory_allocation_failed;
                    return 1;
                }
            }
            else {
                ec = error_code::malformed_structure;
                if (error_pos)
                    *error_pos = static_cast<int>(start - start);
                return 1;
            }

            start = string_end + 1; // Skip 'e'
            --item_limit;
            continue;
        }
    }

    if (start != end) {
        ec = error_code::trailing_data;
        if (error_pos)
            *error_pos = static_cast<int>(start - start);
        return 1;
    }

    if (stack.size() != 1) {
        ec = error_code::unexpected_end_of_input;
        if (error_pos)
            *error_pos = static_cast<int>(start - start);
        return 1;
    }

    return 0;
